package com.example.yuejie;
import android.content.Context;import java.io.*;import java.util.*;
/** TTText's shipped English patterns and exceptions, with its two-letter edge limits. */
final class ReaderHyphenator {
 static final class Node {final Map<Character,Node> children=new HashMap<>();int[] weights;}
 private static volatile ReaderHyphenator instance;final Node root=new Node();final Map<String,boolean[]> exceptions=new HashMap<>();
 static synchronized void load(Context context){if(instance!=null)return;try{ReaderHyphenator h=new ReaderHyphenator();try(BufferedReader in=new BufferedReader(new InputStreamReader(context.getAssets().open("reader-hyphen-patterns.txt"),"UTF-8"))){for(String line;(line=in.readLine())!=null;)h.pattern(line);}try(BufferedReader in=new BufferedReader(new InputStreamReader(context.getAssets().open("reader-hyphen-exceptions.txt"),"UTF-8"))){for(String line;(line=in.readLine())!=null;){String word=line.replace("-","");boolean[] flags=new boolean[word.length()+1];int pos=0;for(char c:line.toCharArray())if(c=='-')flags[pos]=true;else pos++;h.exceptions.put(word,flags);}}instance=h;}catch(IOException e){throw new IllegalStateException("Reader hyphenation assets missing",e);}}
 private void pattern(String pattern){Node node=root;int[] values=new int[pattern.length()+1];int pos=0;for(char c:pattern.toCharArray()){if(c>='0'&&c<='9')values[pos]=c-'0';else{node=node.children.computeIfAbsent(c,k->new Node());pos++;}}node.weights=Arrays.copyOf(values,pos+1);}
 static boolean[] breaks(String value){boolean[] none=new boolean[value.length()+1];if(instance==null)return none;String word=value.toLowerCase(Locale.ROOT);for(char c:word.toCharArray())if(c<'a'||c>'z')return none;boolean[] saved=instance.exceptions.get(word);if(saved!=null)return saved;String padded="."+word+".";int[] scores=new int[padded.length()+1];for(int start=0;start<padded.length();start++){Node node=instance.root;for(int end=start;end<padded.length();end++){node=node.children.get(padded.charAt(end));if(node==null)break;if(node.weights!=null)for(int i=0;i<node.weights.length;i++)scores[start+i]=Math.max(scores[start+i],node.weights[i]);}}for(int i=2;i<=word.length()-2;i++)none[i]=(scores[i+1]&1)!=0;return none;}
}
